import './App.css';
import WeatherApp from './Components/WeatherApp/WeatherApp';

import search_icon from "../src/Components/Assets/search.png";
import clear_icon from "../src/Components/Assets/clear.png";
import cloud_icon from "../src/Components/Assets/cloud.png";
import drizzle_icon from "../src/Components/Assets/drizzle.png";
import humidity_icon from "../src/Components/Assets/humidity.png";
import rain_icon from "../src/Components/Assets/rain.png";
import snow_icon from "../src/Components/Assets/snow.png";
import wind_icon from "../src/Components/Assets/wind.png";

function App() {
  return (
    <div className="container">
      <div className='top-bar'>
        <input type='text' placeholder='Search' className='cityInput' al></input>
        <div className='search-Icon'>
          <img src={search_icon} alt='search' />
        </div>
      </div>
    </div>
  );
}

export default App;
